  players:[{controller:'human',nation:'China',name:'漢（衛青）',teamId:1,spawn:{lon:108.9,lat:34.27}},{controller:'ai',nation:'Mongolia',name:'匈奴',teamId:2,difficulty:'normal',spawn:{lon:109.7,lat:40.8}}],
