function find(id){for(const g of GROUPS)for(const it of g.items)if(it.id===id)return it;return null}
// 選邊（v2.9，Helen：「劇情戰役應該讓玩家選擇操作哪一方，模擬不同視角」）：
// sides(item) 列出可扮演的對戰方：非旁觀、與原玩家不同隊、且不是「休戰中」佔位的 AI 勢力（純經濟局沒有對戰方就不能選邊；lockSide 的局（原住民族守社局）只留守方視角）。
// mirror(item,side) 把目標翻到對方視角：原局是守（有 survive）→ 你變攻方，要在 2 倍時間（至少 20 分）內消滅原玩家；
// 原局是攻（只有 destroy）→ 你變守方，撐過原本的時限（沒有就 15 分）。蓋建築／研究／存資源／奇觀這類原玩家的發展目標與 protect 不翻。
function humanIndex(item){return Math.max(0,item.players.findIndex(p=>p.controller==='human'))}
function sides(item){if(item.kind==='reading'||!item.players||item.lockSide)return [];const h=humanIndex(item),ht=item.players[h].teamId;
 return item.players.map((p,i)=>({index:i,name:p.name,nation:p.nation,teamId:p.teamId})).filter((s,i)=>{const p=item.players[i];return i!==h&&p.controller!=='human'&&!p.passive&&p.teamId!==ht&&!/休戰中/.test(p.name||'')})}
function mirror(item,side){const h=humanIndex(item);const swap=i=>i===h?side:i===side?h:i;const name0=item.players[h].name||'原玩家';
 const surv=item.objectives.find(o=>o.kind==='survive');
 if(surv){const m=Math.max(20,surv.minutes*2);return {objectives:[{kind:'destroy',player:swap(h),text:'在 '+m+' 分鐘內消滅'+name0}],lose:[{kind:'deadline',minutes:m,text:m+' 分鐘內沒攻下就失敗'}]}}
 const dl=(item.lose||[]).find(l=>l.kind==='deadline');const m=dl?dl.minutes:15;
 return {objectives:[{kind:'survive',minutes:m,text:'撐過 '+m+' 分鐘（擋住'+name0+'）'}],lose:[]}}
// 選了邊之後的勢力表：原玩家與所選勢力對調位置（其餘索引不動，旁觀者不受影響），原玩家改由 AI（普通）操作。
function castPlayers(item,side){const h=humanIndex(item);const ps=item.players.map((p,i)=>({...p,leader:p.leader||(item.id+"#"+i)}));/* 先按原始順序蓋上主帥代號，之後選邊對調時會跟著人一起走，不會張冠李戴 */if(side==null||side===h)return ps;
 if(!sides(item).some(s=>s.index===side))throw new Error('這一局不能扮演該勢力');
 const a=ps[h],b=ps[side];ps[h]={...b,controller:'human',difficulty:undefined};ps[side]={...a,controller:'ai',difficulty:'normal'};return ps}
// 產生引擎用的開局設定：人類永遠第 0 號，spawn 隨 players 一起傳給 match.normalize；side（原 players 索引）可改扮演對戰方。
// 選邊時人類與對手的欄位互換，指到勢力編號的設定（艦隊、火攻資格）要跟著換。
function swapSlot(h,side,picked,i){return picked?(i===h?side:(i===side?h:i)):i}
function config(item,seed,side){const h=humanIndex(item);const picked=side!=null&&side!==h;const ps=castPlayers(item,side);const goals=picked?mirror(item,side):{objectives:item.objectives,lose:item.lose||[]};
 return {schemaVersion:1,seed:seed??(Math.random()*4294967296)>>>0,mode:item.mode,map:{id:item.map,size:item.size||'standard',spawnPolicy:'balanced',projection:['World','EastAsia'].includes(item.map)?'mercator':'plate'},
 rules:{startAge:item.startAge,maxAge:item.maxAge??item.startAge,/* Helen 2026-09-24：「我選了火燒連環船的劇情，但是卻可以升級到唐宋，應該鎖定在三國時代才是」→ 劇情戰役預設鎖在該局的時代（maxAge=startAge 會讓 match.js 自動把 lockAge 設為 true，升級鈕消失、AI 也不會升級）；需要升級的局自己寫 maxAge */victory:'scenario',truce:item.truce??0,popCap:item.popCap??150,tutorial:false,lockTeams:item.lockTeams!==false,spawnSpacing:item.spacing||24,timeLimit:item.timeLimit??60,events:item.events!==false},
 players:ps.map(p=>({controller:p.controller,nation:p.nation,teamId:p.teamId,leader:p.leader||null,difficulty:p.difficulty||'normal',name:p.name||null,spawn:p.spawn||null,passive:p.passive===true})),
 scenario:{id:item.id,title:item.title+(picked?'・扮演'+item.players[side].name:''),year:item.year||null,era:item.era||null,advisors:item.advisors||null,fleets:item.fleets?item.fleets.map(f=>({...f,player:swapSlot(h,side,picked,f.player)})):null,wind:item.wind||null,fireAttack:item.fireAttack?item.fireAttack.map(n=>swapSlot(h,side,picked,n)):null,objectives:goals.objectives.map(o=>({...o})),lose:goals.lose.map(o=>({...o}))}}}
root.CAMPAIGNS={GROUPS,find,config,sides,mirror,castPlayers,count:GROUPS.reduce((n,g)=>n+g.items.filter(i=>i.kind!=='reading').length,0),readingCount:GROUPS.reduce((n,g)=>n+g.items.filter(i=>i.kind==='reading').length,0)};
